-- Criterios oficiales EBA-ICA por indicador y tipo de predio (norma 7.x y 9.x).
INSERT INTO indicador_criterios
  (indicador_id, tipo_predio, seccion, criterio_100, criterio_55, criterio_20, criterio_0)
VALUES
  (1, 'PRODUCTIVO', '7.1.1', 'El agua se encuentra disponible en bebederos chupos, zanjas o jagüeyes y por lo menos el 90% de los animales tienen acceso al Recurso.', 'El agua se encuentra disponible en bebederos chupos, zanjas o jagüeyes y entre el 70% y el 89% de los animales tienen acceso al Recurso.', 'El agua se encuentra disponible en bebederos chupos, zanjas o jagüeyes y entre el 40% y el 69% de los animales tienen acceso al Recurso.', 'El agua se encuentra disponible en bebederos chupos, zanjas o jagüeyes y menos del 40% de los animales tienen acceso al Recurso. O El agua no se encuentra disponible en bebederos chupos, zanjas o jagüeyes'),
  (2, 'PRODUCTIVO', '7.1.2', 'Por lo menos el 90% de los animales tienen acceso a una cantidad suficiente de agua y esta es de buena calidad.', 'Entre el 70% y el 89% de los animales tienen acceso a una cantidad suficiente de agua y esta es de buena calidad.', 'Entre el 40% y el 69% de los animales tienen acceso a una cantidad suficiente de agua y esta es de buena calidad. O Más del 69 % de los animales tienen acceso a una cantidad suficiente de agua y esta no es de buena calidad.', 'Menos del 40% de los animales tienen acceso a una cantidad suficiente de agua. O Entre el 40% y el 69% de los animales tienen acceso a una cantidad suficiente de agua y esta no es de buena calidad.'),
  (3, 'PRODUCTIVO', '7.1.3', 'El 90% o más de los bebederos están en buen estado, están limpios, libres de moho y heces en la parte interior.', 'Entre el 70% y el 89% de los bebederos están en buen estado, están limpios, libres de moho y heces en la parte interior, o el predio productivo no hace uso de bebederos o chupos, pero garantiza el acceso al agua.', 'Entre el 40% y el 69% de los bebederos están en buen estado, están limpios, libres de moho y heces en la parte interior.', 'Menos del 40 % de los bebederos están en buen estado o, se evidencia suciedad, moho o heces en la parte interior.'),
  (4, 'PRODUCTIVO', '7.1.4', 'El alimento se encuentra disponible en corrales y praderas y por lo menos el 90% de los animales tienen acceso al Recurso.', 'El alimento se encuentra disponible en corrales y praderas y entre el 70% y el 89% de los animales tienen acceso al Recurso.', 'El alimento se encuentra disponible en corrales y praderas y entre el 40% y el 69% de los animales tienen acceso al Recurso.', 'El alimento se encuentra disponible en corrales y praderas y menos del 40% de los animales tienen acceso al Recurso. O El alimento no se encuentra disponible en corrales y praderas.'),
  (5, 'PRODUCTIVO', '7.1.5', 'El 90% o más de los animales cuentan con suficiente cantidad de alimento en comederos y praderas, el alimento ofrecido en comederos es de buena calidad y se cumplen con las medidas de comederos establecidas.', 'Entre el 70% y el 89% de los animales cuentan con suficiente cantidad de alimento en comederos y praderas y el alimento ofrecido en comederos es de buena calidad O no se cumplen con las medidas de comederos establecidas.', 'Entre el 40% y el 69% de los animales cuentan con suficiente cantidad de alimento en comederos y praderas, el alimento ofrecido en comederos es de buena calidad y se cumplen con las medidas de comederos establecidas.', 'Menos del 40% o más de los animales cuentan con suficiente cantidad de alimento en comederos y praderas O El alimento ofrecido en comederos no es de buena calidad.'),
  (6, 'PRODUCTIVO', '7.1.6', 'Más del 90% de los comederos están en buen estado, están limpios, libres de moho, lama y heces en la parte interior. O todos los animales se alimentan exclusivamente en pastoreo.', 'Entre el 70% y 89% de los comederos están en buen estado; están limpios, libres de moho, lama y heces en la parte interior.', 'Entre el 40% y 69% de los comederos están en buen estado; están limpios, libres de moho, lama y heces en la parte interior.', 'Menos del 40% de los comederos están en buen estado o, se evidencia moho, lama o heces en la parte interior.'),
  (7, 'PRODUCTIVO', '7.1.7', 'Los alimentos y suplementos comerciales se encuentran almacenados correctamente y cuentan con registro ICA.', 'La norma solo define cumplimiento (100 puntos) o no cumplimiento (0 puntos) para este indicador.', 'La norma solo define cumplimiento (100 puntos) o no cumplimiento (0 puntos) para este indicador.', 'Los alimentos y suplementos no se encuentran almacenados correctamente o no cuentan con registro ICA.'),
  (8, 'PRODUCTIVO', '7.1.8', 'Más del 80% de los animales con puntuación de 3 o 4 en una escala de 1 a 5.', 'Del 61 a 80% de los animales con puntuación de 3 o 4 en una escala de 1 a 5.', 'Del 41 a 60% de los animales con puntuación de 3 o 4 en una escala de 1 a 5.', 'Menor o igual a 40% de los animales con puntuación de 3 o 4 en una escala de 1 a 5.'),
  (9, 'PRODUCTIVO', '7.2.1', 'Menos del 10% de los animales observados presentan signos de estrés térmico.', 'Entre el 10% y el 20% de los animales observados presentan signos de estrés térmico.', 'Si entre el 21% y 30% los animales observados presentan signos de estrés térmico.', 'Más del 30% de los animales observados presentan signos de estrés térmico'),
  (10, 'PRODUCTIVO', '7.2.2', 'Mas del 90 % de los animales tienen acceso a sombra en corrales y potreros.', 'Entre el 70% y 89% de los animales tienen acceso a sombra en corrales y potreros.', 'Entre el 40% y 69% de los animales tienen acceso a sombra en corrales y potreros.', 'Menos del 40% de los animales no tienen acceso a sombra en corrales y potreros.'),
  (11, 'PRODUCTIVO', '7.2.3', 'Hay presencia de encharcamientos en menos del 10% de los corrales o potreros y existen suficientes zonas de descanso sin encharcamiento.', 'Hay presencia de encharcamientos entre el 10 % y 20% de los corrales o potreros y existen suficientes zonas de descanso sin encharcamiento', 'Hay presencia de encharcamientos entre el 21% y 30% de los corrales o potreros y existen zonas de descanso sin encharcamiento', 'Hay presencia de encharcamientos en más del 30% de los corrales o potreros y no existen zonas de descanso.'),
  (12, 'PRODUCTIVO', '7.2.4', 'Más del 90% de los espacios revisados se ajusta a los mínimos establecidos o se encuentra por encima de estos.', 'El entre el 70% y 89 % de los espacios revisados se ajusta a los mínimos establecidos o se encuentra por encima de estos.', 'El entre el 40% y 69 % de los espacios revisados se ajusta a los mínimos establecidos o se encuentra por encima de estos.', 'Menos del 40% de los espacios revisados se ajusta a los mínimos establecidos.'),
  (13, 'PRODUCTIVO', '7.2.5', 'En el 100% de los corrales el material del piso no presenta riesgo ni causa lesiones en los animales, se encuentran en buen estado de conservación y limpieza no se presenta acumulación de residuos o algún tipo de materiales extraños al interior de los corrales.', 'Entre el 70% y 99% de los corrales el material del piso no presenta riesgo ni causa lesiones en los animales, se encuentran en buen estado de conservación y limpieza y no se presenta acumulación de residuos o algún tipo de materiales extraños al interior de los corrales.', 'Entre el 40% y 69% de los corrales el material del piso no presenta riesgo ni causa lesiones en los animales, se encuentran en buen estado de conservación y limpieza y no se presenta acumulación de residuos o algún tipo de materiales extraños al interior de los corrales.', 'Menos del 40 % de los corrales el material del piso no presenta riesgo ni causa lesiones en los animales, se encuentran en buen estado de conservación y limpieza y no se presenta acumulación de residuos o algún tipo de materiales extraños al interior de los corrales.'),
  (14, 'PRODUCTIVO', '7.2.6', 'El 100% de las camas inspeccionadas son suaves, contienen suficiente material, no permiten la visualización de áreas del suelo, son de fácil limpieza, desinfección, no tienen elementos que puedan lesionar o causar heridas a los animales, sin olor a amoniaco.', 'Si entre el 70% y 99% de las camas inspeccionadas son suaves, contienen suficiente material, no permiten la visualización de áreas del suelo, son de fácil limpieza, desinfección, no tienen elementos que puedan lesionar o causar heridas a los animales, sin olor a amoniaco.', 'Entre el 40% y 69% de las camas inspeccionadas son suaves, contienen suficiente material, no permiten la visualización de áreas del suelo, son de fácil limpieza, desinfección, no tienen elementos que puedan lesionar o causar heridas a los animales, sin olor a amoniaco.', 'Menos del 40% de las camas inspeccionadas son suaves, contienen suficiente material, no permiten la visualización de áreas del suelo, son de fácil limpieza, desinfección, no tienen elementos que puedan lesionar o causar heridas a los animales, sin olor a amoniaco.'),
  (15, 'PRODUCTIVO', '7.2.7', 'El 100% de los corrales cuentan con iluminación para realizar la inspección de todos los animales y áreas.', 'Entre el 70% y el 99% de los corrales cuentan con iluminación que permite la inspección de todos los animales y áreas.', 'Entre el 50% y el 69% de los corrales cuentan con iluminación que permite la inspección de todos los animales y áreas.', 'Menos del 49% de los corrales cuentan con iluminación que permite la inspección de todos los animales y áreas.'),
  (16, 'PRODUCTIVO', '7.2.8', 'El 100% de los corrales cuentan con ventilación para evitar la concentración de olores.', 'Entre el 70% y el 99% de los corrales cuentan con ventilación que evita la concentración de olores.', 'Entre el 50% y el 69% de los corrales cuentan con ventilación que evita la concentración de olores.', 'Menos del 49% de los corrales cuentan con ventilación que evita la concentración de olores.'),
  (17, 'PRODUCTIVO', '7.3.1', 'Menos del 3% de los animales presentan secreción nasal, o tos.', 'Entre el 4% y 7% de los animales presentan secreción nasal, o tos.', 'Entre el 8% y el 10 % de los animales presentan secreción nasal o tos.', 'Más del 10 % de los animales presentan secreción nasal, ocular y/o tos.'),
  (18, 'PRODUCTIVO', '7.3.2', 'Menos del 3% de los animales presentan secreción ocular.', 'Entre el 4% y 7% de los animales presentan secreción ocular.', 'Entre el 8% y el 10 % de los animales presentan secreción ocular.', 'Más del 10 % de los animales presentan secreción ocular.'),
  (19, 'PRODUCTIVO', '7.3.3', 'Menos del 3% de los animales presentan FAMACHA con calificación 4 o 5.', 'Del 4% al 6% de los animales presentan FAMACHA con calificación 4 o 5.', 'Del 7% al 10% de los animales presentan FAMACHA con calificación 4 o 5.', 'Más del 10% de los animales presentan FAMACHA con calificación 4 o 5.'),
  (20, 'PRODUCTIVO', '7.3.4', 'No se realiza topizado ni descorne. En el caso de realizarse topizado o descorne este se realiza antes de los 10 días de edad y existe evidencia del uso de analgesia y anestesia. Donde todos los animales se encuentren en la misma condición.', 'Se realiza topizado o descorne a edad mayor a 10 días y hay evidencia de uso de anestesia y/o analgesia.', 'La norma no define un nivel de 20 puntos para este indicador; si no cumple las condiciones de 55 puntos, corresponde 0.', 'Se realiza topizado o descorne a edad mayor a 10 días y no hay evidencia de uso de anestesia y/o analgesia.'),
  (21, 'PRODUCTIVO', '7.3.5', 'En ningún animal se observan ectoparásitos.', 'Entre el 1% y 10% de los animales se observa ectoparásitos.', 'Entre el 10% y 20% de los animales se observa ectoparásitos.', 'Más del 20% de los animales presentan ectoparásitos.'),
  (22, 'PRODUCTIVO', '7.3.6', 'Hasta el 3% de los animales presentan alopecias, úlceras, heridas o lesiones en el cuerpo y estas están siendo tratadas.', 'Entre el 4 y 6% de los animales presentan alopecias, úlceras, heridas o lesiones en el cuerpo y estas están siendo tratadas.', 'Del 7% al 10% de los animales presentan alopecias, úlceras, heridas o lesiones en el cuerpo y estas están siendo tratadas, o Menos del 7% de animales presentan úlceras, heridas o lesiones en el cuerpo y estas no son tratadas.', 'Más del 10% de los animales presentan alopecias, úlceras, heridas o lesiones en el cuerpo y no son tratadas.'),
  (23, 'PRODUCTIVO', '7.3.7', 'En los animales evaluados se observa una prevalencia de casos de mastitis clínica menor al 3%.', 'En los animales evaluados se observa una prevalencia de casos de mastitis clínica entre el 3% y 4%.', 'En los animales evaluados se observa una prevalencia de casos de mastitis clínica entre el 4.1% y 5%.', 'En los animales evaluados se observa una prevalencia de casos de mastitis mayor al 5% de mastitis clínica.'),
  (24, 'PRODUCTIVO', '7.3.8', 'No se realiza castración. Se realiza castración con evidencia de uso de anestesia y/o analgesia donde se evite el uso de bandas constrictoras, La intervención quirúrgica es realizada por MV o MVZ y, es realizada a edad menor de 15 días. En caso de castración química se realiza con productos con registro ICA atendiendo a las recomendaciones del rotulado del producto.', 'Se realiza castración sin importar el método con evidencia de uso de anestesia y analgesia. La intervención quirúrgica es realizada por MV o MVZ y, Es realizada a edad menor de 15 días.', 'La norma no define un nivel de 20 puntos para este indicador; si no cumple las condiciones de 55 puntos, corresponde 0.', 'Se realiza castración y, no hay evidencia de uso de anestesia y/o analgesia o, La intervención quirúrgica no es realizada por MV o MVZ o, es realizada a edad mayor a 15 días.'),
  (25, 'PRODUCTIVO', '7.3.9', 'No se realiza descole o En el 100% de los animales descolados se observa descole largo y, Hay evidencia de uso de anestesia y/o analgesia y, El descole con anillo de caucho es realizado a edad menor de 15 días.', 'En 100% de los animales descolados se observa descole largo y, no hay evidencia de uso de anestesia y/o analgesia o, El descole con anillo de caucho es realizado a edad mayor a 15 días.', 'La norma no define un nivel de 20 puntos para este indicador; si no cumple las condiciones de 55 puntos, corresponde 0.', 'Se realiza descole corto.'),
  (26, 'PRODUCTIVO', '7.3.10', 'Más del 3 % de los animales presentan puntuación de 4 o 5.', 'Entre el 4% y el 6% de los animales presentan puntuación de 4 o 5.', 'Entre el 7% y 10 % de los animales presentan puntuación de 4 o 5.', 'Más del 10% de los animales presentan puntuación de 4 o 5.'),
  (27, 'PRODUCTIVO', '7.3.11', 'Hasta el 5% de los animales presentan cojeras.', 'Hasta el 8% de los animales presentan cojeras.', 'Entre el 9% y el 12% de los animales presentan cojeras.', 'Más del 13% de los animales presentan cojeras.'),
  (28, 'PRODUCTIVO', '7.3.12', 'Hasta el 5% de los animales presentan sobre crecimiento de pezuñas.', 'Hasta el 8% de los animales presentan sobre crecimiento de pezuñas.', 'Entre el 9% y el 12% de los animales presentan sobre crecimiento de pezuñas.', 'Más del 13% de los animales presentan sobre crecimiento de pezuñas.'),
  (29, 'PRODUCTIVO', '7.3.13', 'Mortalidad menor o igual al 5% en corderos o cabritos y del 3% en animales adultos y se llevan registros escritos.', 'Mortalidad menor o igual al 5% en corderos o cabritos y del 3% en animales adultos, pero no se llevan registros.', 'Mortalidad entre el 5% y 6% en corderos o cabritos y entre el 3% y 5% en animales adultos.', 'Mortalidad entre el 6% y 7% en corderos o cabritos y del 6% al 8% en animales adultos. O No proporciona información.'),
  (30, 'PRODUCTIVO', '7.3.14', 'Se cumple con todas las BPUMV', 'Se utilizan medicamentos con registro ICA, no se usan sustancias prohibidas o promotores de crecimiento no autorizados por el ICA, los medicamentos son prescritos por MV o MVZ y se llevan registro de tratamientos veterinarios y no se emplean medicamentos vencidos. Se evidencia mal almacenamiento de medicamentos o, las agujas están en mal estado o, el lugar de almacenamiento está sucio.', 'Se utilizan medicamento con registro ICA, no se usan sustancias prohibidas o promotores de crecimiento no autorizados por el ICA, y los medicamentos son prescritos por MV o MVZ y se llevan registro de tratamientos veterinarios y, Se emplean medicamentos vencidos o, mal almacenamiento de medicamentos o, las agujas están en mal estado o, el lugar de almacenamiento está sucio.', 'Utilizan medicamentos sin registro ICA o, Se usan sustancias prohibidas o promotores de crecimiento no autorizados por el ICA, o Los medicamentos no son prescritos por MV o MVZ o, No se llevan registro de tratamientos veterinarios'),
  (31, 'PRODUCTIVO', '7.3.15', 'Existe plan sanitario escrito, firmado por MV o MVZ e implementado y con registros.', 'Existen registros de vacunaciones, control de parásitos internos y externos, pero no hay plan sanitario escrito.', 'Existe plan sanitario, pero no está implementado y no hay registros.', 'No hay plan sanitario ni registros de vacunaciones, no existe evidencia del control de parásitos internos y externos ni evidencias de implementación.'),
  (32, 'PRODUCTIVO', '7.4.1', 'En todos los grupos de animales estos se mantienen tranquilos ante la presencia del manejador, llegando a moverse, pero sin agitación.', 'Los animales se muestran tranquilos ante el humano, pero atentos a sus movimientos.', 'Los animales se muestran intranquilos ante el humano intentando esconderse o huir.', 'Los animales se alejan enérgicamente, saltando unos sobre otros o golpeándose contra las mallas o cercas.'),
  (33, 'PRODUCTIVO', '7.4.2', 'Todas las personas demuestran conocimiento en bienestar y cuentan con certificación escrita.', 'Más del 50% de las personas demuestran conocimiento en temas de bienestar y cuentan con certificación escrita. O El 100% de las personas demuestran conocimiento en bienestar animal pero no poseen certificación.', 'Más del 50% de las personas demuestran conocimiento en temas de bienestar y no cuentan con certificación escrita.', 'Menos del 50% de las personas demuestran conocimiento en bienestar y no cuentan con certificación.'),
  (34, 'PRODUCTIVO', '7.5.1', 'Ningún animal amarrado o con palos amarrados al cuello que limiten su movimiento.', 'Menos del 2% de animales amarrados o con palos amarrados al cuello que limiten su movimiento.', 'Entre el 2% y el 5% de animales amarrados o con palos amarrados al cuello que limiten su movimiento.', 'M?s del 5% de animales amarrados o con palos amarrados al cuello que limiten su movimiento.'),
  (35, 'PRODUCTIVO', '7.5.2', 'Ningún animal se observa aislado del resto del grupo.', 'Menos del 5% de animales se observa aislado del resto del grupo.', 'Entre el 5% y el 10% de animales se observa aislado del resto del grupo.', 'Más del 10% de animales se observa aislado del resto del grupo.'),
  (36, 'PRODUCTIVO', '7.5.3', 'Los animales cuentan con un potrero de descanso y/o elementos de enriquecimiento ambiental.', 'La norma solo define cumplimiento (100 puntos) o no cumplimiento (0 puntos) para este indicador.', 'La norma solo define cumplimiento (100 puntos) o no cumplimiento (0 puntos) para este indicador.', 'No cuentan con potrero de descanso ni elementos de enriquecimiento ambiental.'),
  (1, 'FAMILIAR', '9.1.1', 'El agua se encuentra disponible en bebederos chupos, zanjas o jagüeyes y por lo menos el 90% de los animales tienen acceso al recurso.', 'El agua se encuentra disponible en bebederos chupos, zanjas o jagüeyes y entre el 70% y el 89% de los animales tienen acceso al recurso.', 'El agua se encuentra disponible en bebederos chupos, zanjas o jagüeyes y entre el 40% y el 69% de los animales tienen acceso al recurso.', 'El agua se encuentra disponible en bebederos chupos, zanjas o jagüeyes y menos del 40% de los animales tienen acceso al recurso. O El agua no se encuentra disponible en bebederos chupos, zanjas o jagüeyes'),
  (2, 'FAMILIAR', '9.1.2', 'Por lo menos el 90% de los animales tienen acceso a una cantidad suficiente de agua y esta es de buena calidad.', 'Entre el 70% y el 89% de los animales tienen acceso a una cantidad suficiente de agua y esta es de buena calidad.', 'Entre el 40% y el 69% de los animales tienen acceso a una cantidad suficiente de agua y esta es de buena calidad. O Más del 69 % de los animales tienen acceso a una cantidad suficiente de agua y esta no es de buena calidad.', 'Menos del 40% de los animales tienen acceso a una cantidad suficiente de agua. O Entre el 40% y el 69% de los animales tienen acceso a una cantidad suficiente de agua y esta no es de buena calidad.'),
  (3, 'FAMILIAR', '9.1.3', 'Por lo menos el 90% de los bebederos están en buen estado, están limpios, libres de moho y heces en la parte interior.', 'Entre el 70% y el 89% de los bebederos están en buen estado, están limpios, libres de moho y heces en la parte interior, o el predio productivo no hace uso de bebederos o chupos, pero garantiza el acceso al agua.', 'Entre el 40% y el 69% de los bebederos están en buen estado, están limpios, libres de moho y heces en la parte interior.', 'Menos del 40 % de los bebederos están en buen estado o, se evidencia suciedad, moho o heces en la parte interior.'),
  (4, 'FAMILIAR', '9.1.4', 'El alimento se encuentra disponible y por lo menos el 90% de los animales tienen acceso al Recurso.', 'El alimento se encuentra disponible y entre el 70% y el 89% de los animales tienen acceso al Recurso.', 'El alimento se encuentra disponible y entre el 40% y el 69% de los animales tienen acceso al Recurso.', 'El alimento se encuentra disponible y menos del 40% de los animales tienen acceso al Recurso. O El alimento no se encuentra disponible.'),
  (5, 'FAMILIAR', '9.1.5', 'El 90% o más de los animales cuentan con suficiente cantidad de alimento y este es de buena calidad.', 'Entre el 70% y el 89% de los animales cuentan con suficiente cantidad de alimento y este es de buena calidad.', 'Entre el 40% y el 69% de los animales cuentan con suficiente cantidad de alimento y este es de buena calidad.', 'Menos del 40% o más de los animales cuentan con suficiente cantidad de alimento y este es de buena calidad.'),
  (6, 'FAMILIAR', '9.1.6', 'Por lo menos el 90% de los comederos están en buen estado, están limpios, libres de moho, lama y heces en la parte interior. O todos los animales se alimentan exclusivamente en pastoreo.', 'Entre el 70% y 89% de los comederos están en buen estado; están limpios, libres de moho, lama y heces en la parte interior.', 'Entre el 40% y 69% de los comederos están en buen estado; están limpios, libres de moho, lama y heces en la parte interior.', 'Menos del 40% de los comederos están en buen estado o, se evidencia moho, lama o heces en la parte interior.'),
  (8, 'FAMILIAR', '9.1.7', 'Más del 80% de los animales con puntuación de 3 o 4 en una escala de 1 a 5.', 'De 61 a 80% de los animales con puntuación de 3 o 4 en una escala de 1 a 5.', 'De 41 a 60% de los animales con puntuación de 3 o 4 en una escala de 1 a 5.', 'Menor o igual a 40% de los animales con puntuación de 3 o 4 en una escala de 1 a 5.'),
  (9, 'FAMILIAR', '9.2.1', 'Menos del 10% de los animales presentan signos de estrés térmico.', 'Entre el 11 % y el 20% de los animales presentan signos de estrés térmico.', 'Si entre el 21% y 30% los animales presentan signos de estrés térmico.', 'Más del 30% de los animales presentan signos de estrés térmico'),
  (10, 'FAMILIAR', '9.2.2', 'Mas del 90 % de los animales tienen acceso a sombra en corrales y potreros.', 'Entre el 70% y 89% de los animales tienen acceso a sombra en corrales y potreros.', 'Entre el 40% y 69% de los animales tienen acceso a sombra en corrales y potreros.', 'Menos del 40% de los animales no tienen acceso a sombra en corrales y potreros.'),
  (11, 'FAMILIAR', '9.2.3', 'Hay presencia de encharcamientos en menos del 10% de los corrales o potreros y existen suficientes zonas de descanso sin encharcamiento.', 'Hay presencia de encharcamientos entre el 11 % y 20% de los corrales o potreros y existen suficientes zonas de descanso sin encharcamiento', 'Hay presencia de encharcamientos entre el 21% y 30% de los corrales o potreros y existen zonas de descanso sin encharcamiento', 'Hay presencia de encharcamientos en más del 30% de los corrales o potreros y no existen zonas de descanso.'),
  (12, 'FAMILIAR', '9.2.4', 'Más del 90% de los espacios revisados se ajusta a los mínimos establecidos o se encuentra por encima de estos', 'El entre el 70% y 89 % de los espacios revisados se ajusta a los mínimos establecidos o se encuentra por encima de estos.', 'El entre el 40% y 69 % de los espacios revisados se ajusta a los mínimos establecidos o se encuentra por encima de estos.', 'Menos del 40% de los espacios revisados se ajusta a los mínimos establecidos.'),
  (13, 'FAMILIAR', '9.2.5', 'En el 100% de los corrales el material del piso no presenta riesgo ni causa lesiones en los animales, se encuentran en buen estado de conservación y limpieza no se presenta acumulación de residuos o algún tipo de materiales extraños al interior de los corrales.', 'Entre el 70% y 99% de los corrales el material del piso no presenta riesgo ni causa lesiones en los animales, se encuentran en buen estado de conservación y limpieza y no se presenta acumulación de residuos o algún tipo de materiales extraños al interior de los corrales.', 'Entre el 40% y 69% de los corrales el material del piso no presenta riesgo ni causa lesiones en los animales, se encuentran en buen estado de conservación y limpieza y no se presenta acumulación de residuos o algún tipo de materiales extraños al interior de los corrales.', 'Menos del 40 % de los corrales el material del piso no presenta riesgo ni causa lesiones en los animales, se encuentran en buen estado de conservación y limpieza y no se presenta acumulación de residuos o algún tipo de materiales extraños al interior de los corrales.'),
  (14, 'FAMILIAR', '9.2.6', 'El 100% de las camas inspeccionadas son suaves, contienen suficiente material, no permiten la visualización de áreas del suelo, son de fácil limpieza, desinfección, no tienen elementos que puedan lesionar o causar heridas a los animales, sin olor a amoniaco.', 'Si entre el 70% y 99% de las camas inspeccionadas son suaves, contienen suficiente material, no permiten la visualización de áreas del suelo, son de fácil limpieza, desinfección, no tienen elementos que puedan lesionar o causar heridas a los animales, sin olor a amoniaco.', 'Entre el 40% y 69% de las camas inspeccionadas son suaves, contienen suficiente material, no permiten la visualización de áreas del suelo, son de fácil limpieza, desinfección, no tienen elementos que puedan lesionar o causar heridas a los animales, sin olor a amoniaco.', 'Menos del 40% de las camas inspeccionadas son suaves, contienen suficiente material, no permiten la visualización de áreas del suelo, son de fácil limpieza, desinfección, no tienen elementos que puedan lesionar o causar heridas a los animales, sin olor a amoniaco.'),
  (15, 'FAMILIAR', '9.2.7', 'El 100% de los corrales cuentan con iluminación para realizar la inspección de todos los animales y áreas.', 'Entre el 70% y el 99% de los corrales cuentan con iluminación que permite la inspección de todos los animales y áreas.', 'Entre el 50% y el 69% de los corrales cuentan con iluminación que permite la inspección de todos los animales y áreas.', 'Menos del 49% de los corrales cuentan con iluminación que permite la inspección de todos los animales y áreas.'),
  (16, 'FAMILIAR', '9.2.8', 'El 100% de los corrales cuentan con ventilación para evitar la concentración de olores.', 'Entre el 70% y el 99% de los corrales cuentan con ventilación que evita la concentración de olores.', 'Entre el 50% y el 69% de los corrales cuentan con ventilación que evita la concentración de olores.', 'Menos del 49% de los corrales cuentan con ventilación que evita la concentración de olores.'),
  (17, 'FAMILIAR', '9.3.1', 'Menos del 3% de los animales presentan secreción nasal, o tos.', 'Entre el 4% y 7% de los animales presentan secreción nasal, o tos.', 'Entre el 8% y el 10 % de los animales presentan secreción nasal o tos.', 'Más del 10 % de los animales presentan secreción nasal, o tos.'),
